select c.custid, c.username, c.creatdate,e.currency, ci.credit, creator.username as creator , isnull(xx.username,'') as 'gave credit by'
from customer c with(nolock)
	inner join custInfo ci with(nolock) on c.custid = ci.custid
	inner join custInfo creator with(nolock) on c.creator = creator.custid
	inner join Exchange e with(nolock) on c.currency = e.exchangeid 
	left join #tmp t on c.custid = t.custid
	left join Customer xx with(nolock) on t.userid = xx.custid
where c.custid not in (select custid from Dep_CustSuper with(nolock))
and c.creatdate >= '2014-02-01' 
and c.roleid = 4
and c.currency <> 20
